For the geometric series, we have
\begin{align*}
\sum_{k=1}^{n} x^k &= \frac{x^{n+1}-1}{x-1},
\end{align*}
so for our sum,
\begin{align*}
\sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} &= \frac{1}{4} \sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^k + \omega^{2k} + \omega^{3k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} \\
&\quad+ \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^{2k} + \omega^{3k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^{3k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} \\
&= \frac{1}{4} \sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^{2k} + \omega^{3k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^{2k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} \\
&\quad + \frac{1}{4} \sum_{k=1}^{1728} \frac{\omega^{3k}}{1 + \omega^k + \omega^{2k} + \omega^{3k}} \\
&= \frac{1}{4} \sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{1}{4} \sum_{k=1}^{1728} \frac{(\omega^{3k} + \omega^{4k} + \omega^{5k}) + \omega^{k} + \omega^{k+2}}{\omega^{k} (\omega^{3k} + \omega^{4k} + \omega^{5k})} \\
&= \frac{1}{4} \sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} + \frac{(\omega^{-3} + \omega^{-10} + \omega^{-17}) + \omega^{-1} + \omega^{-13}}{4 \cdot (\omega^{-3} + \omega^{-10} + \omega^{-17})} \\
&= \frac{1}{4} \left[ \frac{1}{1 + \omega + \omega^2 + \omega^3} - \frac{1}{1 + \omega^{1729} + \omega^{1730} + \omega^{1731}} \right] + \frac{-\omega^{-2} - \omega^{-14} - \omega^{-26}}{4 \cdot (\omega^{-3} + \omega^{-10} + \omega^{-17})} \\
&= \frac{1}{4} \left[ \frac{1}{1 + \omega + \omega^2 + \omega^3} - 1 \right] - \frac{(\omega^{-2} + \omega^{-14} + \omega^{-26})}{4 \cdot (\omega^{-3} + \omega^{-10} + \omega^{-17})}
\end{align*}
Since $\omega^{-14}$ and $\omega^{-26}$ are contained in $\omega^{-10}$,
\begin{align*}
\omega^{-2} + \omega^{-14} + \omega^{-26} &= \omega^{-3} + \omega^{-10} - \omega^{-10} = \omega^{-3}
\end{align*}
using the geometric series formula. Therefore,
\begin{align*}
\sum_{k=1}^{1728} \frac{1}{1 + \omega^k + \omega^{2k} + \omega^{3k}} &= \frac{1}{4} \left[ \frac{1}{1 + \omega + \omega^2 + \omega^3} - 1 \right] - \frac{\omega^{-3}}{4 \cdot (\omega^{-3} + \omega^{-10} + \omega^{-17})} \\
&= \frac{1}{4} \left[ \frac{1}{1 + e^{2\pi i/1729} + e^{4\pi i/1729} + e^{6\pi i/1729}} - 1 \right] - \frac{e^{-3\pi i}}{4 (e^{-3\pi i/1729} + e^{-10\pi i/1729} + e^{-17\pi i/1729})}
\end{align*}
Finally,
