question += ' '.join([f{vars[i]} {operations[i]}  for i in range(len(vals))])

equation = question.replace('vars', '\\text{ ') + ' '.join([f{str(v)} for v in vals]).replace(', ', ' ') + question.replace('vars', '')

if variables and question[-2] == '?':
    question += 'Solve step by step.'

print(f{equation}\n\n----------\n)

# Substitutions from variables to constants
answers = {}
for i, v in enumerate(vals):
    if v not in answers:
        answers[variables[i]] = v

answer = 0
for i, j, v in zip(range(len(vals)), range(len(vals) - 1, -1, -1), answers.values()):
    if j == i:
        continue

    if operations[i] == '+':
        answer -= v
    elif operations[i] == '-':
        answer += v
    elif operations[i] == '^':
        answer = answer ** v
    else:
        answer *= v

answer_str = str(answer)
if answer < 0:
    ans_str = f'-{abs(answer)}'
else:
    ans_str = answer_str

if question[-2] == '?':
    lines = [f- If the correct answer has units, write the units OUTSIDE the box in plain text.\n,
