\implies P \cdot (x \begin{bmatrix}1\\0\end{bmatrix} + y \begin{bmatrix}0\\1\end{bmatrix}) &= \begin{bmatrix}0\\y\end{bmatrix} \\
\endimplies P \cdot \begin{bmatrix}1\\0\endbmatrix &= \begin{bmatrix}0\\0\end{bmatrix} \\
\implies P &= -\begin{bmatrix}0\\0\end{bmatrix} \begin{bmatrix}1\\0\end{bmatrix} = \begin{bmatrix}0\\0\end{bmatrix}
