\begin{align*}
\text{ Circle:} & \quad x^2 + y^2 = R^2  \\
\text{ Parabola: } & \quad y^2 = 4px \text{ (directed upwards) } \\
\text{ Ellipse:} & \quad \frac{x^2}{a^2} + \frac{y^2}{b^2} = 1 \\
