\documentclass[12pt]{article}
\usepackage{amsmath}
\usepackage{siunitx}

\begin{document}
\begin{enumerate}
    \item Determine the volume of the 2-cm-by-2cm-by-2cm cube:
    \item Since the volume of the larger cube is increased by 19 cubic centimeters, subtract the smaller cube's volume from the larger cube's volume to find the additional volume: \begin{align}
    \text{Additional Volume} &= \text{Larger Cube's Vol.} - \text{Smaller Cube's Vol.} \\
                 &= \left(2 \times 2 \times 2\si{\cmice Cubic centimeters}\right) + 19 \si{\cmice Cubic centimeters} - \left(2 \times 2 \times 2\si{\cmice Cubic centimeters}\right) \\
                 &= 8\si{\cmice Cubic centimeters} + 19 \si{\cmice Cubic centimeters} - 8\si{\cmice Cubic centimeters} \\
                 &= \boxed{19 \si{\cmice Cubic centimeters}}
    \end{align}
    \item Divide the additional volume by the volume of one cubic centimeter to find the increase in the side length (cube root of a number is the cube root of the absolute value of the number):
    \[
    \text{Increased Side Length} = \sqrt[3]{\text{Additional Volume} / \text{Volume of one cubic centimeter}} = \sqrt[3]{\frac{19}{\si{\cmice Cubic centimeter}}}
    \]
    \item Simplify the resulting expression and take the cube root:
    \begin{align}
    \text{Simplified Increased Side Length} &= \text{Cube Root of} \left(\frac{19}{\si{\cmice Cubic centimeter}}\right) \\
                 &= \sqrt[3]{\frac{19}{\si{\cmice Cubic centimeter}}}\text{.} \\
                 &= \sqrt[3]{\frac{19}{\si{1\cmice Cubic centimeter}}}\text{.} \\
                 &= \si{\sqrt[3]{\frac{19}{\si{1\cmice}}}}\text{.} \\
                 &= \si{\sqrt[3]{19/.000001}}\text{.} \\
                 &= \si{\sqrt[3]{1900000}}\text{.} \\
                 &= \boxed{20 \si{\cmice}} \\
                 \text{ units }
    \end{align}

\end{enumerate}

\end{document}

